// 'autorisation_requise' : espèce dont la détention exige un certificat de capacité
// et une autorisation d'ouverture dès le premier spécimen (arrêté du 8 octobre 2018,
// annexe 2, colonne c) : impossible pour un particulier, donc pas de vente entre particuliers.
export type StatutLegal = 'autorise' | 'cites_a_signaler' | 'autorisation_requise' | 'interdite';

export type CategorieEspece =
  | 'Eau Douce'
  | 'Poissons marins'
  | 'Coraux et anémones'
  | 'Invertébrés marins'
  | 'Macroalgues marines'
  | 'Bassin'
  | 'Plantes'
  | 'Crustacés / Invertébrés eau douce'
  | 'Mollusques eau douce';

export interface InfosPlante {
  placement:
    | 'Arrière-plan'
    | 'Milieu de bac'
    | 'Avant-plan'
    | 'Tapis'
    | 'Fixée sur bois ou roche'
    | 'Flottante'
    | 'Plante de bassin'
    | 'Plante de berge';
  lumiere: 'Faible' | 'Moyenne' | 'Forte';
  croissance: 'Lente' | 'Moyenne' | 'Rapide';
  co2: 'Inutile' | 'Recommandé' | 'Indispensable';
  multiplication: string;
}

// Renseigné pour tout le vivant marin (poissons, coraux, invertébrés, macroalgues).
export interface InfosMarin {
  // Salinité conseillée, ex. « 1,023 – 1,025 (33 – 35 g/L) ».
  salinite: string;
  // Zone d'origine, ex. « Indo-Pacifique ».
  origine: string;
  // Poissons et invertébrés : compatibilité avec un bac récifal (coraux, invertébrés).
  reefSafe?: 'Oui' | 'Avec précautions' | 'Non';
  // Poissons et invertébrés : niveau de la colonne d'eau fréquenté.
  zone?: 'Surface' | 'Milieu' | 'Fond' | 'Tous niveaux';
  // Coraux et bénitiers : paramètres chimiques conseillés (texte libre avec unités).
  kh?: string;
  calcium?: string;
  magnesium?: string;
}

export interface InfosCorail {
  type: 'Corail mou' | 'LPS' | 'SPS' | 'Anémone' | 'Corallimorphe' | 'Zoanthaire' | 'Gorgone' | 'Autre';
  lumiere: 'Faible' | 'Moyenne' | 'Forte';
  courant: 'Faible' | 'Modéré' | 'Fort';
  placement: 'Sol / sable' | 'Bas de roche' | 'Milieu de roche' | 'Haut de roche';
  croissance: 'Lente' | 'Moyenne' | 'Rapide';
  agressivite: 'Paisible' | 'Semi-agressif' | 'Agressif';
  multiplication: string;
}

export interface InfosAlgue {
  placement: 'Sable' | 'Roche' | 'Refuge (bac technique)' | 'Flottante' | 'Libre';
  lumiere: 'Faible' | 'Moyenne' | 'Forte';
  croissance: 'Lente' | 'Moyenne' | 'Rapide';
  // Rôle principal dans le bac, ex. « Exportation des nitrates et phosphates ».
  usage: string;
  // Risque de prolifération ou de nuisance.
  risque: 'Faible' | 'Modéré' | 'Élevé';
  multiplication: string;
}

export interface FicheTechnique {
  description: string;
  conseil: string;
  volumeMinLitres: number | null;
  tailleGroupeMin: number | null;
  compatibilite: string;
  incompatibilite: string;
  phMin: number | null;
  phMax: number | null;
  tempMin: number | null;
  tempMax: number | null;
  difficulte: 'Débutant' | 'Intermédiaire' | 'Expert';
  alimentation: string;
  tailleAdulte: string;
  // Renseigné pour les plantes seulement : remplace, sur la page, les cases
  // « volume minimum » et « groupe minimum » qui n'ont pas de sens pour elles.
  plante?: InfosPlante;
  marin?: InfosMarin;
  corail?: InfosCorail;
  algue?: InfosAlgue;
  reproduction?: {
    facilite: 'Très facile' | 'Facile' | 'Modérée' | 'Difficile' | 'Très difficile' | 'Impossible en captivité';
    description: string;
  };
}

export interface Espece {
  id: number;
  slug: string;
  categorie: CategorieEspece;
  nomCommun: string;
  nomScientifique: string;
  statutLegal: StatutLegal;
  remarqueLegale: string | null;
  citesAnnexe: string | null;
  // Autres noms français ou noms de vente usités : affichés sur la fiche, utilisés par la
  // recherche et déclarés à Google (alternateName).
  autresNoms?: string[];
  // Renseigné uniquement une fois la fiche technique rédigée — voir ESPECES_PUBLIEES.
  fiche?: FicheTechnique;
}

